# 💻 FULL MASTER C CODE — ALL SORTS, ALL CASES
```c
#include <stdio.h>

// =============================
// 🔹 1. BUBBLE SORT
// =============================
void bubbleSort(int a[], int n, int ascending) {
    for (int i = 0; i < n - 1; ++i) {
        int swapped = 0;
        for (int j = 0; j < n - 1 - i; ++j) {
            if ((ascending && a[j] > a[j + 1]) || (!ascending && a[j] < a[j + 1])) {
                int temp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = temp;
                swapped = 1;
            }
        }
        if (!swapped) break; // early exit for best case
    }
}

// =============================
// 🔹 2. SELECTION SORT
// =============================
void selectionSort(int a[], int n, int ascending) {
    for (int i = 0; i < n - 1; ++i) {
        int target = i;
        for (int j = i + 1; j < n; ++j) {
            if ((ascending && a[j] < a[target]) || (!ascending && a[j] > a[target])) {
                target = j;
            }
        }
        if (target != i) {
            int temp = a[i];
            a[i] = a[target];
            a[target] = temp;
        }
    }
}

// =============================
// 🔹 3. INSERTION SORT
// =============================
void insertionSort(int a[], int n, int ascending) {
    for (int i = 1; i < n; ++i) {
        int key = a[i];
        int j = i - 1;
        while (j >= 0 && ((ascending && a[j] > key) || (!ascending && a[j] < key))) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;
    }
}

// =============================
// 🔹 UTILITY FUNCTIONS
// =============================
void printArray(int a[], int n) {
    for (int i = 0; i < n; ++i) printf("%d ", a[i]);
    printf("\n");
}

void copyArray(int src[], int dest[], int n) {
    for (int i = 0; i < n; ++i) dest[i] = src[i];
}

// =============================
// 🔹 MAIN: TEST ALL CASES
// =============================
int main() {
    int arr_best[] = {1, 2, 3, 4, 5};
    int arr_worst[] = {5, 4, 3, 2, 1};
    int arr_avg[] = {3, 1, 4, 5, 2};
    int n = 5;

    int temp[5];

    printf("=========== BUBBLE SORT ===========\n");
    printf("Best (Ascending): "); copyArray(arr_best, temp, n); bubbleSort(temp, n, 1); printArray(temp, n);
    printf("Worst (Ascending): "); copyArray(arr_worst, temp, n); bubbleSort(temp, n, 1); printArray(temp, n);
    printf("Average (Ascending): "); copyArray(arr_avg, temp, n); bubbleSort(temp, n, 1); printArray(temp, n);
    printf("Descending Example: "); copyArray(arr_avg, temp, n); bubbleSort(temp, n, 0); printArray(temp, n);

    printf("\n=========== SELECTION SORT ===========\n");
    printf("Best (Ascending): "); copyArray(arr_best, temp, n); selectionSort(temp, n, 1); printArray(temp, n);
    printf("Worst (Ascending): "); copyArray(arr_worst, temp, n); selectionSort(temp, n, 1); printArray(temp, n);
    printf("Average (Ascending): "); copyArray(arr_avg, temp, n); selectionSort(temp, n, 1); printArray(temp, n);
    printf("Descending Example: "); copyArray(arr_avg, temp, n); selectionSort(temp, n, 0); printArray(temp, n);

    printf("\n=========== INSERTION SORT ===========\n");
    printf("Best (Ascending): "); copyArray(arr_best, temp, n); insertionSort(temp, n, 1); printArray(temp, n);
    printf("Worst (Ascending): "); copyArray(arr_worst, temp, n); insertionSort(temp, n, 1); printArray(temp, n);
    printf("Average (Ascending): "); copyArray(arr_avg, temp, n); insertionSort(temp, n, 1); printArray(temp, n);
    printf("Descending Example: "); copyArray(arr_avg, temp, n); insertionSort(temp, n, 0); printArray(temp, n);

    return 0;
}
